package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"gocode/internal/loop"
	"gocode/internal/model"
	"gocode/internal/session"
	"gocode/internal/settings"
	"gocode/internal/subagent"
	"gocode/internal/tool"
	toolexec "gocode/internal/tool/exec"
	toolfile "gocode/internal/tool/file"
	toolwebfetch "gocode/internal/tool/webfetch"
	uiiface "gocode/internal/ui"
	bubbleui "gocode/internal/ui/bubble"
	"gocode/internal/ui/headless"
	"io"
	"log"
	"os"
	"strings"
)

type options struct {
	prompt         string
	sessionID      string
	subagentWorker bool
}

func parseOptions() options {
	prompt := flag.String("p", "", "single-turn prompt; omit to start Bubble Tea UI")
	sessionID := flag.String("s", "", "session ID; omit to resume/create by cwd")
	subagentWorker := flag.Bool("subagent-worker", false, "run hidden subagent worker")
	flag.Parse()

	return options{
		prompt:         *prompt,
		sessionID:      *sessionID,
		subagentWorker: *subagentWorker,
	}
}

func main() {
	opts := parseOptions()
	ctx := context.Background()

	if opts.subagentWorker {
		if err := runSubagentWorkerMode(ctx, os.Stdin, os.Stdout); err != nil {
			log.Fatal(err)
		}
		return
	}

	if opts.prompt != "" {
		if err := runSingleTurnMode(ctx, opts); err != nil {
			log.Fatal(err)
		}
		return
	}

	if err := runInteractiveMode(ctx, opts); err != nil {
		log.Fatal(err)
	}
}

func runSingleTurnMode(ctx context.Context, opts options) error {
	output := headless.New(os.Stdout)
	runner, sessionID, _, _, _, _, err := buildRunner(ctx, opts.sessionID, output)
	if err != nil {
		return err
	}

	fmt.Fprintf(os.Stderr, "session: %s\n", sessionID)
	_, err = runner.RunTurn(ctx, opts.prompt)
	return err
}

func runInteractiveMode(ctx context.Context, opts options) error {
	clearTerminalWindow(os.Stdout)

	output := bubbleui.New()
	runner, sessionID, client, settingsController, subagentManager, store, err := buildRunner(ctx, opts.sessionID, output)
	if err != nil {
		return err
	}

	output.SetModelConfigController(client)
	output.SetSettingsController(settingsController)
	output.SetSubagentController(subagentManager)
	output.SetSessionStore(store)
	return output.Run(ctx, runner, sessionID)
}

func runSubagentWorkerMode(ctx context.Context, input io.Reader, output io.Writer) error {
	var req subagent.WorkerRequest
	if err := json.NewDecoder(input).Decode(&req); err != nil {
		return fmt.Errorf("decode subagent worker request: %w", err)
	}
	if strings.TrimSpace(req.SessionID) == "" {
		return fmt.Errorf("subagent worker session_id is required")
	}

	runner, sessionID, _, _, _, _, err := buildRunnerWithSubagentContext(ctx, req.SessionID, headless.New(io.Discard), subagentRuntimeContext{
		depth:        req.Depth,
		maxDepth:     req.MaxDepth,
		parentTaskID: req.TaskID,
	})
	result := subagent.WorkerResult{
		TaskID:    req.TaskID,
		SessionID: sessionID,
		ExitCode:  0,
	}
	if err != nil {
		result.Error = err.Error()
		result.ExitCode = 1
		return json.NewEncoder(output).Encode(result)
	}

	msg, err := runner.RunTurn(ctx, req.Prompt)
	if err != nil {
		result.Error = err.Error()
		result.ExitCode = 1
		result.UsedTokens = runner.ContextStats(1<<30, "").UsedTokens
		return json.NewEncoder(output).Encode(result)
	}
	result.Content = strings.TrimSpace(msg.Content)
	result.UsedTokens = runner.ContextStats(1<<30, "").UsedTokens
	return json.NewEncoder(output).Encode(result)
}

func clearTerminalWindow(w io.Writer) {
	if w == nil {
		return
	}
	_, _ = io.WriteString(w, "\x1b[H\x1b[2J\x1b[3J")
}

type subagentRuntimeContext struct {
	depth        int
	maxDepth     int
	parentTaskID string
}

func buildRunner(ctx context.Context, sessionIDFlag string, output uiiface.UI) (*loop.Runner, string, *model.Client, *settings.Controller, *subagent.Manager, *session.JSONLStore, error) {
	return buildRunnerWithSubagentContext(ctx, sessionIDFlag, output, subagentRuntimeContext{})
}

func buildRunnerWithSubagentContext(ctx context.Context, sessionIDFlag string, output uiiface.UI, subCtx subagentRuntimeContext) (*loop.Runner, string, *model.Client, *settings.Controller, *subagent.Manager, *session.JSONLStore, error) {
	cfg, err := model.LoadConfigFromEnv()
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}

	root, err := os.Getwd()
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}

	store, err := session.NewJSONLStoreInCwd()
	if err != nil {
		return nil, "", nil, nil, nil, nil, fmt.Errorf("初始化 session store 失败: %w", err)
	}

	sessionID, err := resolveSessionID(ctx, store, sessionIDFlag, root)
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}

	client := model.NewClient(cfg)
	settingsController, err := settings.NewControllerInCwd()
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}
	var notifier subagent.Notifier
	if n, ok := output.(subagent.Notifier); ok {
		notifier = n
	}
	executable, err := os.Executable()
	if err != nil {
		return nil, "", nil, nil, nil, nil, fmt.Errorf("resolve executable: %w", err)
	}
	registry := tool.NewRegistry()
	runner := loop.NewRunnerWithInstructionRoot(client, output, registry, store, sessionID, root)
	subagentManager := subagent.NewManager(subagent.Config{
		Model:        client,
		Store:        store,
		Root:         root,
		Settings:     settingsController,
		Notifier:     notifier,
		Context:      runner,
		Launcher:     subagent.NewProcessLauncher(executable, root),
		Depth:        subCtx.depth,
		MaxDepth:     subCtx.maxDepth,
		ParentTaskID: subCtx.parentTaskID,
	})
	runner.SetStreamMASubagentRunner(streamMASubagentAdapter{
		manager:         subagentManager,
		parentSessionID: sessionID,
	})
	runner.SetSubagentTokensProvider(subagentManager)
	registerTools(registry, root, subagentManager, sessionID)

	return runner, sessionID, client, settingsController, subagentManager, store, nil
}

type streamMASubagentAdapter struct {
	manager         *subagent.Manager
	parentSessionID string
}

func (a streamMASubagentAdapter) RunStreamMASubagent(ctx context.Context, req loop.StreamMASubagentRequest) (loop.StreamMASubagentResult, error) {
	if a.manager == nil {
		return loop.StreamMASubagentResult{}, fmt.Errorf("streamma subagent manager is nil")
	}
	result, err := a.manager.Run(ctx, subagent.Request{
		ParentSessionID: a.parentSessionID,
		Prompt:          req.Prompt,
		Description:     req.Description,
		ContextMode:     settings.ContextMode(req.ContextMode),
		RunMode:         settings.RunModeSync,
	})
	if err != nil {
		return loop.StreamMASubagentResult{}, err
	}
	return loop.StreamMASubagentResult{
		Content:        result.Content,
		SessionID:      result.SessionID,
		TranscriptPath: result.TranscriptPath,
		OutputPath:     result.OutputPath,
	}, nil
}

func registerTools(registry *tool.Registry, root string, subagentManager *subagent.Manager, sessionID string) {
	if registry == nil {
		return
	}
	registry.Register(&toolfile.LSTool{Root: root})
	registry.Register(&toolfile.ReadTool{Root: root})
	registry.Register(&toolfile.WriteTool{Root: root})
	registry.Register(&toolfile.GrepTool{Root: root})
	registry.Register(&toolfile.GlobTool{Root: root})
	registry.Register(&toolexec.BashTool{Root: root})
	registry.Register(&toolwebfetch.Tool{})
	registry.Register(subagent.NewTool(subagentManager, sessionID))
	registry.Register(subagent.NewStatusTool(subagentManager))
	registry.Register(subagent.NewStopTool(subagentManager))
}

func resolveSessionID(ctx context.Context, store *session.JSONLStore, sessionIDFlag, cwd string) (string, error) {
	if sessionIDFlag != "" {
		exists, err := store.Exists(ctx, sessionIDFlag)
		if err != nil {
			return "", fmt.Errorf("查询 session 失败: %w", err)
		}
		if !exists {
			return "", fmt.Errorf("session 不存在: %s", sessionIDFlag)
		}
		return sessionIDFlag, nil
	}

	sessionID, err := session.GenerateSessionID()
	if err != nil {
		return "", fmt.Errorf("生成 session ID 失败: %w", err)
	}
	return sessionID, nil
}

package message

import "encoding/json"

type Role string

const (
	RoleSystem    Role = "system"
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
)

type Message struct {
	Role        Role         `json:"role"`
	Content     string       `json:"content,omitempty"`
	ToolUse     *ToolCall    `json:"tool_use,omitempty"`
	ToolUses    []ToolCall   `json:"tool_uses,omitempty"`
	ToolResult  *ToolResult  `json:"tool_result,omitempty"`
	ToolResults []ToolResult `json:"tool_results,omitempty"`
}

type ToolCall struct {
	ID    string          `json:"id"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input"`
}

type ToolResult struct {
	ToolUseID string `json:"tool_use_id"`
	Content   string `json:"content"`
	IsError   bool   `json:"is_error"`
}

package model

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"gocode/internal/message"
	"io"
	"net/http"
	"strings"
	"sync"
)

// Client 封装模型调用的 HTTP 客户端。
// 这一层只负责请求发送、响应解析、错误格式化。
type Client struct {
	httpClient *http.Client
	mu         sync.RWMutex
	cfg        Config
}

// NewClient 创建模型客户端。
func NewClient(cfg Config) *Client {
	return &Client{
		httpClient: &http.Client{Timeout: cfg.Timeout},
		cfg:        cfg,
	}
}

func (c *Client) streamHTTPClient() *http.Client {
	c.mu.RLock()
	defer c.mu.RUnlock()
	if c.httpClient == nil {
		return &http.Client{}
	}
	client := *c.httpClient
	client.Timeout = 0
	return &client
}

func (c *Client) setRequestHeaders(req *http.Request) {
	cfg := c.CurrentModelConfig()
	req.Header.Set("Content-Type", "application/json")
	if strings.TrimSpace(cfg.APIKey) != "" {
		req.Header.Set("Authorization", "Bearer "+cfg.APIKey)
	}
}

func (c *Client) CurrentModelConfig() Config {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.cfg
}

func (c *Client) ApplyModelConfig(cfg Config) error {
	cfg = fillConfigDefaults(cfg)
	if strings.TrimSpace(cfg.APIKey) == "" {
		cfg.APIKey = loadAPIKeyByEnvName(cfg.APIKeyEnvName, nil)
	}
	cfg.APIKey = sanitizeAPIKey(cfg.Provider, cfg.APIKey)

	c.mu.Lock()
	defer c.mu.Unlock()
	c.cfg = cfg
	c.httpClient.Timeout = cfg.Timeout
	return nil
}

func (c *Client) SaveModelConfig(cfg Config) error {
	return SaveModelConfig(cfg)
}

// RunMessage 执行一次最小“输入 -> 输出”调用。
// 当前支持消息列表输入。
func (c *Client) RunMessage(ctx context.Context, messages []message.Message) (string, error) {
	if len(messages) == 0 {
		return "", fmt.Errorf("messages 不能为空")
	}

	cfg := c.CurrentModelConfig()

	reqBody := ChatCompletionsRequest{
		Model:    cfg.Model,
		Messages: messages,
	}

	bodyBytes, err := json.Marshal(reqBody)
	if err != nil {
		return "", fmt.Errorf("序列化请求体失败: %w", err)
	}

	req, err := http.NewRequestWithContext(
		ctx,
		http.MethodPost,
		cfg.APIBaseURL+cfg.APIPath,
		bytes.NewReader(bodyBytes),
	)
	if err != nil {
		return "", fmt.Errorf("创建 HTTP 请求失败: %w", err)
	}

	c.setRequestHeaders(req)

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("调用模型接口失败: %w", err)
	}
	defer func(Body io.ReadCloser) {
		err := Body.Close()
		if err != nil {
			return
		}
	}(resp.Body)

	respBytes, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("读取响应体失败: %w", err)
	}

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return "", fmt.Errorf("模型接口返回异常状态 %d: %s", resp.StatusCode, strings.TrimSpace(string(respBytes)))
	}

	var parsed ChatCompletionsResponse
	if err := json.Unmarshal(respBytes, &parsed); err != nil {
		return "", fmt.Errorf("解析响应 JSON 失败: %w", err)
	}

	if parsed.Error != nil {
		return "", fmt.Errorf("模型接口返回错误: %s", parsed.Error.Message)
	}

	if len(parsed.Choices) == 0 {
		return "", fmt.Errorf("模型接口未返回任何 choices")
	}

	content := strings.TrimSpace(parsed.Choices[0].Message.Content)
	if content == "" {
		return "", fmt.Errorf("模型接口返回了空内容")
	}

	return content, nil
}

package model

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"gocode/internal/message"
	"io"
	"net/http"
	"sort"
	"strings"
)

// StreamEvent 表示一次流式输出事件。
// 一个事件只表达一种状态：
// 1) Delta 非空：收到一段增量文本
// 2) Done=true：流结束
// 3) Err 非空：流中出现错误
type StreamEvent struct {
	Delta     string
	Thinking  string
	ToolCalls []message.ToolCall
	Done      bool
	Err       error
	Usage     *Usage
}

// chatCompletionsStreamResponse 只建模流式响应里当前需要的字段。
// 不需要的字段故意省略，避免上层依赖供应商完整响应结构。
type chatCompletionsStreamResponse struct {
	Choices []struct {
		Delta struct {
			Content   string          `json:"content"`
			ToolCalls []toolCallDelta `json:"tool_calls,omitempty"`
		} `json:"delta"`
		FinishReason *string `json:"finish_reason"`
	} `json:"choices"`
	Usage *Usage `json:"usage,omitempty"`
	Error *struct {
		Message string `json:"message"`
		Type    string `json:"type"`
	} `json:"error,omitempty"`
}

// toolCallDelta 是 OpenAI 兼容接口流式 tool_calls 的单个增量。
type toolCallDelta struct {
	Index    int    `json:"index"`
	ID       string `json:"id"`
	Type     string `json:"type"`
	Function struct {
		Name      string `json:"name"`
		Arguments string `json:"arguments"`
	} `json:"function"`
}

// StreamMessage 以 SSE 方式返回模型增量输出。
// 调用方拿到 channel 后持续 range：
// - 处理 Delta
// - 处理 Err
// - 收到 Done 后结束当前轮次
func (c *Client) StreamMessage(ctx context.Context, messages []message.Message, tools []ToolDefinition) (<-chan StreamEvent, error) {
	// 模型接口要求至少有一条输入消息。
	if len(messages) == 0 {
		return nil, fmt.Errorf("messages 不能为空")
	}

	cfg := c.CurrentModelConfig()
	if shouldAttemptAnthropicStream(cfg) {
		events, err := c.streamAnthropicMessage(ctx, cfg, messages, tools)
		if err == nil {
			return events, nil
		}
	}

	return c.streamOpenAIMessage(ctx, cfg, messages, tools)
}

func (c *Client) streamOpenAIMessage(ctx context.Context, cfg Config, messages []message.Message, tools []ToolDefinition) (<-chan StreamEvent, error) {
	// 启用 stream=true，让服务端按 SSE 增量返回。
	reqBody := ChatCompletionsRequest{
		Model:         cfg.Model,
		Messages:      messages,
		Stream:        true,
		StreamOptions: &StreamOptions{IncludeUsage: true},
	}
	for _, t := range tools {
		reqBody.Tools = append(reqBody.Tools, openAITool{Type: "function", Function: t})
	}

	// 组装 JSON 请求体。
	bodyBytes, err := json.Marshal(reqBody)
	if err != nil {
		return nil, fmt.Errorf("序列化请求体失败: %w", err)
	}

	// 将上层 context 透传到底层 HTTP 请求，支持超时/取消。
	req, err := http.NewRequestWithContext(
		ctx,
		http.MethodPost,
		cfg.APIBaseURL+cfg.APIPath,
		bytes.NewReader(bodyBytes),
	)
	if err != nil {
		return nil, fmt.Errorf("创建 HTTP 请求失败: %w", err)
	}

	// 当前本地网关沿用标准 JSON 请求体和 Bearer 鉴权头。
	c.setRequestHeaders(req)

	// 发起请求；如果失败直接返回同步错误。
	resp, err := c.streamHTTPClient().Do(req)
	if err != nil {
		return nil, fmt.Errorf("调用模型接口失败: %w", err)
	}

	// SSE 流建立失败（非 2xx）时，读取错误体后返回。
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		respBytes, readErr := io.ReadAll(resp.Body)
		_ = resp.Body.Close()
		if readErr != nil {
			return nil, fmt.Errorf("模型接口返回异常状态 %d，且读取错误响应失败: %w", resp.StatusCode, readErr)
		}
		return nil, fmt.Errorf("模型接口返回异常状态 %d: %s", resp.StatusCode, strings.TrimSpace(string(respBytes)))
	}

	// 这里开始转入异步消费：
	// - 调用方立即拿到 channel，不阻塞当前 goroutine
	// - 后台 goroutine 负责解析 SSE 并投递事件
	events := make(chan StreamEvent)
	go c.consumeStream(ctx, resp, events)
	return events, nil
}

func shouldAttemptAnthropicStream(cfg Config) bool {
	baseURL := strings.ToLower(strings.TrimSpace(cfg.APIBaseURL))
	apiPath := strings.ToLower(strings.TrimSpace(cfg.APIPath))
	return normalizeProvider(cfg.Provider) == ProviderDeepSeek ||
		strings.Contains(baseURL, "/anthropic") ||
		strings.HasSuffix(apiPath, "/messages")
}

const (
	streamScannerInitialBufferBytes = 64 * 1024
	streamScannerMaxTokenBytes      = 32 * 1024 * 1024
)

func newStreamScanner(body io.Reader) *bufio.Scanner {
	scanner := bufio.NewScanner(body)
	scanner.Buffer(make([]byte, 0, streamScannerInitialBufferBytes), streamScannerMaxTokenBytes)
	return scanner
}

func (c *Client) handleStreamLine(ctx context.Context, line string, events chan<- StreamEvent) (done bool, err error) {
	line = strings.TrimSpace(line)
	if line == "" {
		return false, nil
	}
	if !strings.HasPrefix(line, "data:") {
		return false, nil
	}

	payload := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
	return c.handleStreamPayload(ctx, payload, events)
}

func (c *Client) handleStreamPayload(ctx context.Context, payload string, events chan<- StreamEvent) (done bool, err error) {
	if payload == "" {
		return false, nil
	}
	if payload == "[DONE]" {
		_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
		return true, nil
	}

	chunk, err := decodeStreamChunk(payload)
	if err != nil {
		return false, fmt.Errorf("解析流式数据失败: %w", err)
	}
	if chunk.Error != nil {
		return false, fmt.Errorf("模型接口返回错误: %s", chunk.Error.Message)
	}

	return emitChunkEvents(ctx, chunk, events), nil
}

func decodeStreamChunk(payload string) (chatCompletionsStreamResponse, error) {
	var chunk chatCompletionsStreamResponse
	err := json.Unmarshal([]byte(payload), &chunk)
	return chunk, err
}

func emitChunkEvents(ctx context.Context, chunk chatCompletionsStreamResponse, events chan<- StreamEvent) (done bool) {
	if chunk.Usage != nil {
		if !emitStreamEvent(ctx, events, StreamEvent{Usage: chunk.Usage}) {
			return true
		}
	}
	if len(chunk.Choices) == 0 {
		return false
	}

	delta := chunk.Choices[0].Delta.Content
	if delta != "" {
		if !emitStreamEvent(ctx, events, StreamEvent{Delta: delta}) {
			return true
		}
	}

	finishReason := chunk.Choices[0].FinishReason
	if finishReason != nil && *finishReason != "" {
		_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
		return true
	}

	return false
}

// activeOpenAIToolCall 追踪正在流式累积的 OpenAI tool_call 增量。
type activeOpenAIToolCall struct {
	id   string
	name string
	args strings.Builder
}

func openAIToolCallsFromAccumulated(accumulated map[int]*activeOpenAIToolCall) []message.ToolCall {
	calls := make([]message.ToolCall, 0, len(accumulated))
	indexes := make([]int, 0, len(accumulated))
	for index := range accumulated {
		indexes = append(indexes, index)
	}
	sort.Ints(indexes)
	for _, index := range indexes {
		call := accumulated[index]
		if call == nil || call.name == "" {
			continue
		}
		args := call.args.String()
		input := json.RawMessage(`{}`)
		if len(args) > 0 && json.Valid([]byte(args)) {
			input = json.RawMessage(args)
		}
		calls = append(calls, message.ToolCall{
			ID:    call.id,
			Name:  call.name,
			Input: input,
		})
	}
	return calls
}

// consumeStream 负责把 SSE 文本行转换为 StreamEvent，并累积原生 tool_calls。
func (c *Client) consumeStream(ctx context.Context, resp *http.Response, events chan<- StreamEvent) {
	defer close(events)
	defer func(Body io.ReadCloser) {
		_ = Body.Close()
	}(resp.Body)

	scanner := newStreamScanner(resp.Body)
	// 按 index 累积 tool_calls，支持单次响应中多个工具调用
	accumulated := map[int]*activeOpenAIToolCall{}

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || !strings.HasPrefix(line, "data:") {
			continue
		}
		payload := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
		if payload == "" || payload == "[DONE]" {
			break
		}

		chunk, err := decodeStreamChunk(payload)
		if err != nil {
			_ = emitStreamEvent(ctx, events, StreamEvent{Err: fmt.Errorf("解析流式数据失败: %w", err)})
			return
		}
		if chunk.Error != nil {
			_ = emitStreamEvent(ctx, events, StreamEvent{Err: fmt.Errorf("模型接口返回错误: %s", chunk.Error.Message)})
			return
		}

		// 累积 delta.tool_calls
		if len(chunk.Choices) > 0 {
			for _, tc := range chunk.Choices[0].Delta.ToolCalls {
				call, ok := accumulated[tc.Index]
				if !ok {
					call = &activeOpenAIToolCall{}
					accumulated[tc.Index] = call
				}
				if tc.ID != "" {
					call.id = tc.ID
				}
				if tc.Function.Name != "" {
					call.name = tc.Function.Name
				}
				call.args.WriteString(tc.Function.Arguments)
			}
		}

		// Usage
		if chunk.Usage != nil {
			if !emitStreamEvent(ctx, events, StreamEvent{Usage: chunk.Usage}) {
				return
			}
		}

		if len(chunk.Choices) == 0 {
			continue
		}

		// 文本内容 delta
		if delta := chunk.Choices[0].Delta.Content; delta != "" {
			if !emitStreamEvent(ctx, events, StreamEvent{Delta: delta}) {
				return
			}
		}

		// finish_reason：先 flush 工具调用，再发 Done
		finishReason := chunk.Choices[0].FinishReason
		if finishReason != nil && *finishReason != "" {
			if calls := openAIToolCallsFromAccumulated(accumulated); len(calls) > 0 {
				if !emitStreamEvent(ctx, events, StreamEvent{ToolCalls: calls}) {
					return
				}
			}
			_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
			return
		}
	}

	if err := scanner.Err(); err != nil {
		_ = emitStreamEvent(ctx, events, StreamEvent{Err: fmt.Errorf("读取流式响应失败: %w", err)})
		return
	}

	// EOF 前未收到 finish_reason：flush 积累的工具调用后发 Done
	if calls := openAIToolCallsFromAccumulated(accumulated); len(calls) > 0 {
		if !emitStreamEvent(ctx, events, StreamEvent{ToolCalls: calls}) {
			return
		}
	}
	_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
}

// emitStreamEvent 在 ctx 取消时主动放弃发送，避免 goroutine 卡在 channel send 上，
// 从而保证 resp.Body 的 defer Close 可以执行。
func emitStreamEvent(ctx context.Context, events chan<- StreamEvent, ev StreamEvent) bool {
	select {
	case events <- ev:
		return true
	case <-ctx.Done():
		return false
	}
}

package model

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const (
	ProviderCustom   = "custom"
	ProviderDeepSeek = "deepseek"

	CustomAPIBaseURL    = "http://localhost:8317/v1"
	CustomChatPath      = "/chat/completions"
	CustomDefaultAPIKey = "sk-dummy"
	legacyCustomModel   = "gpt-5.4-xhigh"
	CustomDefaultModel  = "gpt-5.5"
	CustomAPIKeyEnvName = "NEWAPI_API_KEY"

	DeepSeekAPIBaseURL    = "https://api.deepseek.com"
	DeepSeekChatPath      = "/chat/completions"
	DeepSeekDefaultModel  = "deepseek-chat"
	DeepSeekAPIKeyEnvName = "DEEPSEEK_API_KEY"

	defaultTimeoutSeconds = 60
	modelConfigPath       = ".ccagent/model.json"
)

var apiKeyEnvNames = []string{
	CustomAPIKeyEnvName,
	DeepSeekAPIKeyEnvName,
}

var placeholderAPIKeys = map[string]struct{}{
	"":               {},
	"dummy":          {},
	"your_key_here":  {},
	"your-key-here":  {},
	"<your_api_key>": {},
}

type Config struct {
	Provider      string
	APIBaseURL    string
	APIPath       string
	APIKey        string
	APIKeyEnvName string
	Model         string
	Timeout       time.Duration
}

type persistedModelConfig struct {
	Provider      string `json:"provider"`
	APIBaseURL    string `json:"api_base_url"`
	APIPath       string `json:"api_path"`
	APIKeyEnvName string `json:"api_key_env_name"`
	Model         string `json:"model"`
	Timeout       int    `json:"timeout_seconds,omitempty"`
}

func LoadConfigFromEnv() (Config, error) {
	fileEnvValues, err := loadOptionalEnvFiles(".env", ".env.local")
	if err != nil {
		return Config{}, err
	}

	cfg := defaultConfigForProvider(ProviderCustom)
	persisted, err := loadPersistedModelConfig()
	if err != nil {
		return Config{}, err
	}
	if persisted != nil {
		cfg = mergePersistedConfig(cfg, *persisted)
	}

	cfg.Provider = normalizeProvider(cfg.Provider)
	cfg = fillConfigDefaults(cfg)
	cfg.APIKey = sanitizeAPIKey(cfg.Provider, loadAPIKeyByEnvName(cfg.APIKeyEnvName, fileEnvValues))
	if cfg.Provider == ProviderCustom && cfg.APIKey == "" {
		cfg.APIKey = CustomDefaultAPIKey
	}
	if providerRequiresAPIKey(cfg.Provider) && cfg.APIKey == "" {
		return Config{}, fmt.Errorf("missing %s", cfg.APIKeyEnvName)
	}
	return cfg, nil
}

func SaveModelConfig(cfg Config) error {
	cfg = fillConfigDefaults(cfg)
	if err := os.MkdirAll(filepath.Dir(modelConfigPath), 0o755); err != nil {
		return fmt.Errorf("create config directory: %w", err)
	}

	payload := persistedModelConfig{
		Provider:      cfg.Provider,
		APIBaseURL:    cfg.APIBaseURL,
		APIPath:       cfg.APIPath,
		APIKeyEnvName: cfg.APIKeyEnvName,
		Model:         cfg.Model,
		Timeout:       int(cfg.Timeout / time.Second),
	}

	data, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal model config: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(modelConfigPath, data, 0o600); err != nil {
		return fmt.Errorf("write model config: %w", err)
	}
	return nil
}

func defaultConfigForProvider(provider string) Config {
	switch normalizeProvider(provider) {
	case ProviderCustom:
		return Config{
			Provider:      ProviderCustom,
			APIBaseURL:    CustomAPIBaseURL,
			APIPath:       CustomChatPath,
			APIKeyEnvName: CustomAPIKeyEnvName,
			Model:         CustomDefaultModel,
			Timeout:       defaultTimeout(),
		}
	default:
		return Config{
			Provider:      ProviderDeepSeek,
			APIBaseURL:    DeepSeekAPIBaseURL,
			APIPath:       DeepSeekChatPath,
			APIKeyEnvName: DeepSeekAPIKeyEnvName,
			Model:         DeepSeekDefaultModel,
			Timeout:       defaultTimeout(),
		}
	}
}

func defaultTimeout() time.Duration {
	return time.Duration(defaultTimeoutSeconds) * time.Second
}

func normalizeProvider(provider string) string {
	switch strings.ToLower(strings.TrimSpace(provider)) {
	case ProviderCustom:
		return ProviderCustom
	case ProviderDeepSeek:
		return ProviderDeepSeek
	default:
		return ProviderCustom
	}
}

func fillConfigDefaults(cfg Config) Config {
	defaults := defaultConfigForProvider(cfg.Provider)
	cfg.Provider = defaults.Provider
	if strings.TrimSpace(cfg.APIBaseURL) == "" {
		cfg.APIBaseURL = defaults.APIBaseURL
	}
	if strings.TrimSpace(cfg.APIPath) == "" {
		cfg.APIPath = defaults.APIPath
	}
	if strings.TrimSpace(cfg.APIKeyEnvName) == "" {
		cfg.APIKeyEnvName = defaults.APIKeyEnvName
	}
	if strings.TrimSpace(cfg.Model) == "" {
		cfg.Model = defaults.Model
	}
	if cfg.Timeout <= 0 {
		cfg.Timeout = defaults.Timeout
	}
	return cfg
}

func mergePersistedConfig(base Config, persisted persistedModelConfig) Config {
	cfg := base
	if strings.TrimSpace(persisted.Provider) != "" {
		cfg.Provider = persisted.Provider
	}
	if strings.TrimSpace(persisted.APIBaseURL) != "" {
		cfg.APIBaseURL = persisted.APIBaseURL
	}
	if strings.TrimSpace(persisted.APIPath) != "" {
		cfg.APIPath = persisted.APIPath
	}
	if strings.TrimSpace(persisted.APIKeyEnvName) != "" {
		cfg.APIKeyEnvName = persisted.APIKeyEnvName
	}
	if strings.TrimSpace(persisted.Model) != "" {
		cfg.Model = normalizePersistedModel(cfg.Provider, persisted.Model)
	}
	if persisted.Timeout > 0 {
		cfg.Timeout = time.Duration(persisted.Timeout) * time.Second
	}
	return cfg
}

func loadPersistedModelConfig() (*persistedModelConfig, error) {
	data, err := os.ReadFile(modelConfigPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("read model config: %w", err)
	}

	var persisted persistedModelConfig
	if err := json.Unmarshal(data, &persisted); err != nil {
		return nil, fmt.Errorf("parse model config: %w", err)
	}
	return &persisted, nil
}

func loadAPIKeyByEnvName(primary string, values map[string]string) string {
	primary = strings.TrimSpace(primary)
	if primary == "" {
		return ""
	}
	if value := strings.TrimSpace(values[primary]); value != "" {
		return value
	}
	if value := strings.TrimSpace(os.Getenv(primary)); value != "" {
		return value
	}
	return ""
}

func normalizePersistedModel(provider, modelName string) string {
	modelName = strings.TrimSpace(modelName)
	if normalizeProvider(provider) == ProviderCustom && modelName == legacyCustomModel {
		return CustomDefaultModel
	}
	return modelName
}

func providerRequiresAPIKey(provider string) bool {
	return normalizeProvider(provider) != ProviderCustom
}

func sanitizeAPIKey(provider, key string) string {
	key = strings.TrimSpace(key)
	if providerRequiresAPIKey(provider) {
		return key
	}
	if _, ok := placeholderAPIKeys[strings.ToLower(key)]; ok {
		return ""
	}
	return key
}

func loadOptionalEnvFiles(paths ...string) (map[string]string, error) {
	loaded := make(map[string]string)
	for _, path := range paths {
		if err := loadOptionalEnvFile(path, loaded); err != nil {
			return nil, err
		}
	}
	return loaded, nil
}

func loadOptionalEnvFile(path string, loaded map[string]string) error {
	file, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("open %s: %w", path, err)
	}
	defer func() {
		_ = file.Close()
	}()

	scanner := bufio.NewScanner(file)
	for lineNo := 1; scanner.Scan(); lineNo++ {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		line = strings.TrimSpace(strings.TrimPrefix(line, "export "))
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			return fmt.Errorf("%s:%d invalid env line", path, lineNo)
		}

		key = strings.TrimSpace(key)
		if key == "" {
			return fmt.Errorf("%s:%d missing env key", path, lineNo)
		}

		value = trimEnvValue(strings.TrimSpace(value))
		if err := os.Setenv(key, value); err != nil {
			return fmt.Errorf("set env %s: %w", key, err)
		}
		loaded[key] = value
	}

	if err := scanner.Err(); err != nil {
		return fmt.Errorf("scan %s: %w", path, err)
	}
	return nil
}

func trimEnvValue(value string) string {
	if len(value) >= 2 {
		if value[0] == '"' && value[len(value)-1] == '"' {
			return value[1 : len(value)-1]
		}
		if value[0] == '\'' && value[len(value)-1] == '\'' {
			return value[1 : len(value)-1]
		}
	}
	return value
}

