type subagentTool struct {
	manager         *Manager
	parentSessionID string
}

type statusTool struct {
	manager *Manager
}

type stopTool struct {
	manager *Manager
}

type toolInput struct {
	Prompt      string               `json:"prompt"`
	Description string               `json:"description,omitempty"`
	ContextMode settings.ContextMode `json:"context_mode,omitempty"`
	RunMode     settings.RunMode     `json:"run_mode,omitempty"`
}

type statusInput struct {
	ID string `json:"id,omitempty"`
}

type stopInput struct {
	ID string `json:"id"`
}

func NewTool(manager *Manager, parentSessionID string) tool.Tool {
	return &subagentTool{manager: manager, parentSessionID: parentSessionID}
}

func NewStatusTool(manager *Manager) tool.Tool {
	return &statusTool{manager: manager}
}

func NewStopTool(manager *Manager) tool.Tool {
	return &stopTool{manager: manager}
}

func (t *subagentTool) Name() string {
	return "Subagent"
}

func (t *subagentTool) Description() string {
	return "Launch a focused subagent. Use context_mode empty for a self-contained spec, or fork to inherit committed parent session history. run_mode defaults to background and returns a task id immediately; explicit sync waits for the result."
}

func (t *subagentTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"prompt":{"type":"string"},"description":{"type":"string"},"context_mode":{"type":"string","enum":["empty","fork"]},"run_mode":{"type":"string","enum":["sync","background"],"default":"background"}},"required":["prompt"]}`)
}

func (t *subagentTool) buildRequest(raw json.RawMessage) (Request, error) {
	var in toolInput
	if err := json.Unmarshal(raw, &in); err != nil {
		return Request{}, err
	}
	req := Request{
		ParentSessionID: t.parentSessionID,
		Prompt:          in.Prompt,
		Description:     in.Description,
		ContextMode:     in.ContextMode,
		RunMode:         in.RunMode,
	}
	if req.RunMode == "" {
		req.RunMode = settings.RunModeBackground
	}
	req = t.manager.normalizeRequest(req)
	return req, nil
}

func (t *subagentTool) IsConcurrencySafe(raw json.RawMessage) bool {
	req, err := t.buildRequest(raw)
	return err == nil && req.RunMode == settings.RunModeBackground
}

func (t *subagentTool) Run(ctx context.Context, raw json.RawMessage) (string, error) {
	req, err := t.buildRequest(raw)
	if err != nil {
		return "", err
	}
	if req.RunMode == settings.RunModeBackground {
		task, err := t.manager.Launch(ctx, req)
		if err != nil {
			return "", err
		}
		return marshalResult(task), nil
	}
	result, err := t.manager.Run(ctx, req)
	if err != nil {
		return "", err
	}
	return marshalResult(result), nil
}

func (t *statusTool) Name() string {
	return "SubagentStatus"
}

func (t *statusTool) Description() string {
	return "List background subagent tasks or get one task by id."
}

func (t *statusTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"id":{"type":"string"}}}`)
}

func (t *statusTool) IsConcurrencySafe(json.RawMessage) bool {
	return t != nil && t.manager != nil
}

func (t *statusTool) Run(ctx context.Context, raw json.RawMessage) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
	var in statusInput
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &in); err != nil {
			return "", err
		}
	}
	if strings.TrimSpace(in.ID) != "" {
		task, ok := t.manager.Status(in.ID)
		if !ok {
			return "", fmt.Errorf("subagent task not found: %s", in.ID)
		}
		return marshalResult(task), nil
	}
	return marshalResult(t.manager.ListTasks()), nil
}

func (t *stopTool) Name() string {
	return "SubagentStop"
}

func (t *stopTool) Description() string {
	return "Stop a running background subagent task by id."
}

func (t *stopTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"id":{"type":"string"}},"required":["id"]}`)
}

func (t *stopTool) Run(ctx context.Context, raw json.RawMessage) (string, error) {
	var in stopInput
	if err := json.Unmarshal(raw, &in); err != nil {
		return "", err
	}
	task, err := t.manager.Stop(ctx, in.ID)
	if err != nil {
		return marshalResult(task), err
	}
	return marshalResult(task), nil
}

func marshalResult(v any) string {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return fmt.Sprintf("%v", v)
	}
	return string(data)
}

func TranscriptPath(root, sessionID string) string {
	return filepath.Join(root, ".ccagent", "sessions", sessionID, "transcript.jsonl")
}

package ui

import "encoding/json"

// ToolCallEvent 描述一次工具调用事件。
// UI 只关心展示，因此这里保留最小字段集合。
type ToolCallEvent struct {
	ID         string
	Name       string
	Input      json.RawMessage
	OldContent string // 文件变更工具执行前的旧文件内容（Write/Edit），由调用方在工具执行前同步读取
}

// ToolResultEvent 描述一次工具执行结果事件。
// Name 单独保留一份，避免 UI 还要再从其他结构推断工具名。
type ToolResultEvent struct {
	ToolUseID string
	Name      string
	Content   string
	IsError   bool
}

// SystemEvent 描述由后台任务或控制器产生的系统消息。
type SystemEvent struct {
	Title string
	Body  string
	Color string // 可选：标题颜色（lipgloss 颜色字符串），与 subagents 面板保持一致
}

// UI 定义 loop 层依赖的最小输出接口。
// 当前既要支持纯文本流式渲染，也要支持工具调用/结果事件展示。
type UI interface {
	OnAssistantDelta(text string) error
	OnToolCall(event ToolCallEvent) error
	OnToolResult(event ToolResultEvent) error
	OnDone() error
}

// ThinkingDeltaReceiver 是 UI 的可选扩展，用于接收模型 thinking 流。
type ThinkingDeltaReceiver interface {
	OnThinkingDelta(text string) error
}

// SystemNotifier 是 UI 的可选扩展，用于接收后台任务完成等系统事件。
type SystemNotifier interface {
	OnSystemMessage(event SystemEvent) error
}

// OldContentConsumer 是 UI 的可选扩展，声明该 UI 会消费 ToolCallEvent.OldContent。
// 未实现此接口的 UI（如 sinkUI）不会触发磁盘读取，避免浪费 I/O。
type OldContentConsumer interface {
	ConsumesOldContent() bool
}

package headless

import (
	"fmt"
	"gocode/internal/ui"
	"io"
	"strings"
	"sync"
)

// UI 提供最小的 headless stdout 渲染能力。
// 设计目标：
// 1) 增量内容立即输出（模拟打字流）
// 2) 一轮结束时统一补换行
// 3) 在并发场景下保持输出与状态一致
type UI struct {
	// out 是输出目标，通常为 os.Stdout。
	out io.Writer
	// mu 保护 out 写入和 wrote 状态，避免并发调用时交叉写。
	mu sync.Mutex
	// wrote 标记“本轮是否已经写过内容”，用于决定 OnDone 是否补换行。
	wrote bool
}

var _ ui.UI = (*UI)(nil)

// New 创建 headless UI。
func New(out io.Writer) *UI {
	return &UI{out: out}
}

// OnAssistantDelta 输出增量文本。
// 调用方每收到一段 delta 就调用一次。
func (u *UI) OnAssistantDelta(text string) error {
	// 空增量无需输出，减少无意义写操作。
	if text == "" {
		return nil
	}

	// 锁住“写输出 + 更新状态”这两个动作，保证它们原子化。
	u.mu.Lock()
	defer u.mu.Unlock()

	// 将当前增量直接写到终端，不做缓存，保证流式体验。
	if _, err := io.WriteString(u.out, text); err != nil {
		return err
	}
	// 记录本轮已输出过内容，供 OnDone 判断是否需要补换行。
	u.wrote = true
	return nil
}

// OnToolCall 输出工具调用事件。
// 工具事件单独成行，避免和 assistant 流式文本混在一起。
func (u *UI) OnToolCall(event ui.ToolCallEvent) error {
	u.mu.Lock()
	defer u.mu.Unlock()

	if err := u.startEventLineLocked(); err != nil {
		return err
	}

	input := strings.TrimSpace(string(event.Input))
	if input == "" {
		input = "{}"
	}

	_, err := fmt.Fprintf(u.out, "[tool] %s %s\n", event.Name, input)
	return err
}

// OnToolResult 输出工具结果事件。
// 这里默认只打印简短摘要，避免把大块工具输出直接刷到终端。
func (u *UI) OnToolResult(event ui.ToolResultEvent) error {
	u.mu.Lock()
	defer u.mu.Unlock()

	if err := u.startEventLineLocked(); err != nil {
		return err
	}

	status := "ok"
	if event.IsError {
		status = "error"
	}

	preview := summarizeToolContent(event.Content)
	if preview == "" {
		_, err := fmt.Fprintf(u.out, "[tool-result] %s %s\n", event.Name, status)
		return err
	}

	_, err := fmt.Fprintf(u.out, "[tool-result] %s %s: %s\n", event.Name, status, preview)
	return err
}

// OnSystemMessage 输出后台任务等系统事件。
func (u *UI) OnSystemMessage(event ui.SystemEvent) error {
	u.mu.Lock()
	defer u.mu.Unlock()

	if err := u.startEventLineLocked(); err != nil {
		return err
	}
	title := strings.TrimSpace(event.Title)
	if title == "" {
		title = "system"
	}
	_, err := fmt.Fprintf(u.out, "[system] %s: %s\n", title, strings.TrimSpace(event.Body))
	return err
}

// OnDone 在一轮流式输出结束后补一个换行。
// 这样下一次日志/提示不会紧贴在模型输出后面。
func (u *UI) OnDone() error {
	u.mu.Lock()
	defer u.mu.Unlock()

	// 本轮无输出时不补换行，避免产生空白行噪声。
	if !u.wrote {
		return nil
	}

	// 补一个换行，完成本轮渲染收尾。
	if _, err := io.WriteString(u.out, "\n"); err != nil {
		return err
	}
	// 重置轮次状态，准备下一轮输出。
	u.wrote = false
	return nil
}

func (u *UI) startEventLineLocked() error {
	if !u.wrote {
		return nil
	}
	if _, err := io.WriteString(u.out, "\n"); err != nil {
		return err
	}
	u.wrote = false
	return nil
}

func summarizeToolContent(content string) string {
	trimmed := strings.Join(strings.Fields(content), " ")
	if trimmed == "" {
		return ""
	}

	const maxPreviewRunes = 120
	runes := []rune(trimmed)
	if len(runes) <= maxPreviewRunes {
		return trimmed
	}
	return string(runes[:maxPreviewRunes]) + "..."
}

